D.themes=[
{id:"th1",t:"Сдержанность против пышности",q:"Как барокко отвечает на конфессию и характер страны?",items:[["wren","Рен убирает изгибы: прямые линии и ясные объёмы."],["burlington","Чизвик: ни завитков, ни волют, ни статуй на крыше."],["versailles","Масштаб Версаля англичанам не по средствам и не по вкусу."]],more:"Позже сравни с другими главами о барокко: что в них считается признаком «эмоционального» стиля?"},
{id:"th2",t:"Правила и разум",q:"Чем руководствуются, когда говорят «хороший вкус»?",items:[["palladio","Трактат как собрание правил и образцов."],["pope","Правила вкуса приравниваются к правилам разума."],["reynolds","Нормативная система, выведенная из шедевров."],["hogarth","И он верит, что вкусу можно научить. Правило: извилистая линия красивее прямой."]],more:"Заметь, что даже противники академизма (Гейнсборо) работают внутри стиля времени."},
{id:"th3",t:"Портрет",q:"Что показывает портрет: статус, характер или привязанность?",items:[["vandyck","Эталон светского портрета."],["reynolds","Характер и роль модели; детская непосредственность."],["gainsborough","Скользящий мазок, непосредственное впечатление."],["houdon","Бюст как портрет характера (Вольтер)."]],more:"Сравни ил. 305 и 306, а также ил. 267 из главы о Веласкесе."},
{id:"th4",t:"Пейзаж как вымысел",q:"Где природа «сочинена», и чьи образцы она берёт?",items:[["claude","Эталон для парков."],["kent","Пейзажный парк вокруг палладианской виллы."],["gainsborough","Сочинённый пейзаж в наброске."],["fragonard","Реальный вид, превращённый в поэтическое зрелище."]],more:"Стаурхед показывает сразу два образца: Палладио для «храма» и Клода для пейзажа."},
{id:"th5",t:"Рассказ, мораль и тихий быт",q:"Для кого картина и что она хочет сказать?",items:[["hogarth","Серии как нравоучительные новеллы."],["chardin","Нет ни эффектов, ни аллюзий: тихий момент."],["vermeer","Образец для домашнего покоя."]],more:"Хогарт объясняет, зачем нужна живопись. Шарден этого не объясняет, и в этом его сила."},
{id:"th6",t:"Кто у кого учится",q:"Какие образцы из прошлого стоят за каждым именем?",items:[["reynolds","Рафаэль, Тициан, Карраччи, ван Дейк."],["hogarth","Голландцы и венецианцы."],["gainsborough","Хальс и Ватто."],["houdon","Бернини."],["burlington","Палладио и античный храм."]],more:"Хорошее упражнение: нарисовать стрелки «ученик → образец» от руки в книге."}
];
