D.quiz=[
{q:"Что поручили Кристоферу Рену после пожара 1666 года?",o:["Построить Версаль в Англии","Восстановить лондонские церкви","Реформировать Королевскую академию","Описать виллы Палладио"],a:1,e:"Собор Св. Павла стал главным из его проектов."},
{q:"Чем собор Св. Павла принципиально отличается от римской церкви Борромини, хотя элементы у них те же?",o:["В нём нет купола","В нём прямые линии и устойчивость вместо барочных изгибов","Он значительно меньше","Он построен без портика"],a:1,e:"Купол, башни и портик те же, но образ совершенно иной."},
{q:"Какой дом считался идеалом английской аристократии XVIII века?",o:["Дворец вроде Версаля","Замок","Загородный дом","Городской особняк"],a:2,e:"Бленхейм называется исключением."},
{q:"Какая вилла послужила образцом для Чизвик-хауса?",o:["Вилла д'Эсте","Вилла Ротонда Палладио","Бельведер князя Евгения","Бленхейм"],a:1,e:"Лорд Берлингтон близко повторил Ротонду."},
{q:"Чего нет в Чизвик-хаусе?",o:["Портика","Коринфских колонн","Волют, завитков и статуй на крыше","Гладких стен"],a:2,e:"Создатели виллы нигде не грешат против строгих правил."},
{q:"Чей живописный пейзаж был эталоном для английских мастеров садов?",o:["Рубенса","Клода Лоррена","Хальса","Тициана"],a:1,e:"Его влияние Гомбрих находит в усадьбе Стаурхед."},
{q:"Что придумал Хогарт?",o:["Портретные бюсты","Живописные серии о добродетели и пороке","Пейзажный парк","Рисунки сангиной"],a:1,e:"Например «Карьера мота» и «Четыре степени жестокости»."},
{q:"На чём главным образом зарабатывал Хогарт?",o:["На портретах аристократии","На гравюрах со своих картин","На преподавании в академии","На продаже итальянских картин"],a:1,e:"Как живописца знатоки его всерьёз не принимали."},
{q:"Кто был первым президентом Королевской академии художеств?",o:["Хогарт","Гейнсборо","Рейнолдс","Цоффани"],a:2,e:"В его речах изложена академическая доктрина."},
{q:"Какую пару Гомбрих приводит для сравнения Рейнолдса и Гейнсборо?",o:["Рафаэль и Микеланджело","Карраччи и Караваджо","Ватто и Шарден","Ван Дейк и Рубенс"],a:1,e:"Учёный, ищущий идеал, и бунтарь, у которого учитель только природа."},
{q:"Кого Шарден напоминает по настроению тихих домашних сцен?",o:["Бернини","Вермера","Тициана","Пуссена"],a:1,e:"Стр. 432, ил. 281."},
{q:"Кто автор бюста Вольтера и чью традицию он продолжает?",o:["Гудон, Бернини","Фрагонар, Ватто","Рен, Палладио","Шарден, Вермер"],a:0,e:"Стр. 436, ил. 284."},
{q:"Главная мысль главы в одной фразе:",o:["Барокко победило везде","Англия и Франция идут к разуму, ясности и обращению к обычным людям","Живопись исчезла в XVIII веке","Главное достижение эпохи: скульптура"],a:1,e:"Протестантская сдержанность и «век разума» против пышности барокко."}
];
